;(() => {
  if (typeof window === 'undefined' || window.__KIB_AUTO_IDENTIFY_LOADED) return;
  window.__KIB_AUTO_IDENTIFY_LOADED = true;

  // Injeta estilos no documento
  const st = document.createElement('style');
  st.id = 'kib-auto-styles';
  st.textContent = "\n  @keyframes kibGlow {\n    0% { border-color: #00e676 !important; box-shadow: 0 0 0 3px rgba(0,230,118,0.35) !important; background: rgba(0,230,118,0.08) !important; }\n    100% { border-color: inherit; box-shadow: none; background: transparent; }\n  }\n  .kib-glow { animation: kibGlow 1.8s ease-out !important; }\n  .kib-badge-status {\n    display: flex; align-items: flex-start; gap: 12px;\n    background: linear-gradient(180deg, rgba(0,230,118,0.16), rgba(0,230,118,0.05));\n    border: 1px solid rgba(0,230,118,0.45); border-radius: 8px;\n    padding: 12px 16px; margin: 12px 0 16px; font-size: 14.5px; line-height: 1.45;\n    animation: kibFadeIn 0.25s ease-out; color: #f7faf6;\n  }\n  .kib-badge-status svg { stroke: #00e676; flex: none; margin-top: 2px; }\n  .kib-badge-status strong { display: block; font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: #00e676; margin-bottom: 3px; }\n  .kib-badge-status b { color: #00e676; }\n  .kib-badge-buscando {\n    display: flex; align-items: center; gap: 10px;\n    background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.15);\n    border-radius: 8px; padding: 10px 14px; margin: 10px 0 14px;\n    font-size: 14px; color: #a8b2aa; animation: kibFadeIn 0.2s ease-out;\n  }\n  .kib-spinner {\n    width: 16px; height: 16px; border: 2px solid rgba(255,255,255,0.2);\n    border-top-color: #00e676; border-radius: 50%; animation: kibSpin 0.6s linear infinite; flex: none;\n  }\n  @keyframes kibSpin { to { transform: rotate(360deg); } }\n  @keyframes kibFadeIn { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }\n";
  if (!document.getElementById('kib-auto-styles')) {
    (document.head || document.documentElement).appendChild(st);
  }

  const dig = (v) => String(v || '').replace(/\D/g, '');
  const mascaraCPF = (v) => {
    const d = dig(v).slice(0, 11);
    return d.length > 9 ? `${d.slice(0, 3)}.${d.slice(3, 6)}.${d.slice(6, 9)}-${d.slice(9)}`
         : d.length > 6 ? `${d.slice(0, 3)}.${d.slice(3, 6)}.${d.slice(6)}`
         : d.length > 3 ? `${d.slice(0, 3)}.${d.slice(3)}`
         : d;
  };
  const mascaraFone = (v) => {
    const d = dig(v).slice(0, 11);
    return d.length <= 2 ? d.replace(/^(\d{1,2})/, '($1')
         : d.length <= 6 ? d.replace(/^(\d{2})(\d+)/, '($1) $2')
         : d.length <= 10 ? d.replace(/^(\d{2})(\d{4})(\d+)/, '($1) $2-$3')
         : d.replace(/^(\d{2})(\d{5})(\d+)/, '($1) $2-$3');
  };
  const mascaraData = (v) => {
    if (!v) return '';
    let s = String(v).trim();
    if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
      const [y, m, d] = s.slice(0, 10).split('-');
      return `${d}/${m}/${y}`;
    }
    const d = dig(s).slice(0, 8);
    return d.length > 4 ? `${d.slice(0, 2)}/${d.slice(2, 4)}/${d.slice(4)}`
         : d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}`
         : d;
  };
  const mascaraCEP = (v) => {
    const d = dig(v).slice(0, 8);
    return d.length > 5 ? `${d.slice(0, 5)}-${d.slice(5)}` : d;
  };

  function setReactValue(input, val) {
    if (!input || val == null) return;
    const str = String(val).trim();
    if (!str && !input.value) return;
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value')?.set;
    if (setter) {
      setter.call(input, str);
    } else {
      input.value = str;
    }
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
  }

  const cacheClientes = new Map();
  let ctrlAtivo = null;

  function mostrarBanner(container, tipo, texto, nome) {
    if (!container) return;
    let el = container.querySelector('.kib-badge-container');
    if (!el) {
      el = document.createElement('div');
      el.className = 'kib-badge-container';
      container.prepend(el);
    }
    if (tipo === 'buscando') {
      el.innerHTML = `<div class="kib-badge-buscando"><span class="kib-spinner"></span><span>Buscando cadastro no kartódromo…</span></div>`;
    } else if (tipo === 'sucesso') {
      el.innerHTML = `
        <div class="kib-badge-status">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#00e676" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
          <div>
            <strong>Cadastro localizado!</strong>
            <span>Dados de <b>${nome || 'piloto'}</b> preenchidos automaticamente. Você pode revisar e editar qualquer campo.</span>
          </div>
        </div>`;
    } else {
      el.innerHTML = '';
    }
  }

  function preencherResponsavel(c) {
    if (!c) return;
    const campos = [
      { id: 'nome', val: c.nome },
      { id: 'telefone', val: mascaraFone(c.telefone) },
      { id: 'nascimento', val: mascaraData(c.nascimento) },
      { id: 'email', val: c.email },
      { id: 'instagram', val: c.instagram ? (c.instagram.startsWith('@') ? c.instagram : '@' + c.instagram) : '' },
      { id: 'peso', val: c.peso ? String(c.peso).replace('.', ',') : '' },
      { id: 'cep', val: mascaraCEP(c.cep) },
      { id: 'endereco', val: c.rua || c.endereco },
      { id: 'complemento', val: c.complemento },
      { id: 'bairro', val: c.bairro },
      { id: 'cidade', val: c.cidade },
    ];
    campos.forEach(({ id, val }) => {
      const input = document.getElementById(id);
      if (input && val) {
        setReactValue(input, val);
        input.classList.remove('kib-glow');
        void input.offsetWidth;
        input.classList.add('kib-glow');
      }
    });

    const docInput = document.getElementById('documento');
    if (docInput && c.documento) {
      setReactValue(docInput, mascaraCPF(c.documento));
      docInput.classList.remove('kib-glow');
      void docInput.offsetWidth;
      docInput.classList.add('kib-glow');
    }

    const parentForm = docInput?.closest('.fields') || docInput?.parentElement;
    mostrarBanner(parentForm?.parentElement || parentForm, 'sucesso', '', c.nome);
  }

  function preencherAcompanhante(idx, c) {
    if (!c) return;
    const prefix = `ac${idx}-`;
    const campos = [
      { name: prefix + 'nome', val: c.nome },
      { name: prefix + 'telefone', val: mascaraFone(c.telefone) },
      { name: prefix + 'nascimento', val: mascaraData(c.nascimento) },
      { name: prefix + 'email', val: c.email },
      { name: prefix + 'instagram', val: c.instagram ? (c.instagram.startsWith('@') ? c.instagram : '@' + c.instagram) : '' },
      { name: prefix + 'peso', val: c.peso ? String(c.peso).replace('.', ',') : '' },
      { name: prefix + 'cep', val: mascaraCEP(c.cep) },
      { name: prefix + 'endereco', val: c.rua || c.endereco },
      { name: prefix + 'complemento', val: c.complemento },
      { name: prefix + 'bairro', val: c.bairro },
      { name: prefix + 'cidade', val: c.cidade },
    ];
    campos.forEach(({ name, val }) => {
      const input = document.querySelector(`input[name="${name}"]`);
      if (input && val) {
        setReactValue(input, val);
        input.classList.remove('kib-glow');
        void input.offsetWidth;
        input.classList.add('kib-glow');
      }
    });

    const docInput = document.querySelector(`input[name="${prefix}documento"]`);
    if (docInput && c.documento) {
      setReactValue(docInput, mascaraCPF(c.documento));
      docInput.classList.remove('kib-glow');
      void docInput.offsetWidth;
      docInput.classList.add('kib-glow');
    }

    const fieldset = docInput?.closest('fieldset');
    mostrarBanner(fieldset, 'sucesso', '', c.nome);
  }

  async function identificar(raw, isAcIdx = null, containerEl = null) {
    const termo = String(raw || '').trim();
    const d = dig(termo);
    const isEmail = termo.includes('@');
    if (isEmail ? termo.length < 5 : (d.length < 5 && termo.length < 5)) return;

    const cacheKey = isEmail ? termo.toLowerCase() : (d || termo.toUpperCase());
    if (cacheClientes.has(cacheKey)) {
      const c = cacheClientes.get(cacheKey);
      if (isAcIdx !== null) preencherAcompanhante(isAcIdx, c);
      else preencherResponsavel(c);
      return;
    }

    if (ctrlAtivo) ctrlAtivo.abort();
    ctrlAtivo = new AbortController();

    if (containerEl) mostrarBanner(containerEl, 'buscando');

    try {
      const res = await fetch('/api/cliente/identificar', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ identificador: termo }),
        signal: ctrlAtivo.signal
      });
      if (!res.ok) throw new Error('Falha na busca');
      const data = await res.json();
      if (data && data.cliente) {
        cacheClientes.set(cacheKey, data.cliente);
        if (isAcIdx !== null) preencherAcompanhante(isAcIdx, data.cliente);
        else preencherResponsavel(data.cliente);
      } else if (containerEl) {
        mostrarBanner(containerEl, 'nenhum');
      }
    } catch (err) {
      if (err.name === 'AbortError') return;
      if (containerEl) mostrarBanner(containerEl, 'nenhum');
    }
  }

  let debounceTimer = null;
  document.addEventListener('input', (e) => {
    const target = e.target;
    if (!target || target.tagName !== 'INPUT') return;

    if (target.id === 'documento') {
      const d = dig(target.value);
      if (d.length === 11) {
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(() => {
          identificar(d, null, target.closest('.fields')?.parentElement);
        }, 30);
      }
    }

    const acMatch = target.name?.match(/^ac(\d+)-documento$/);
    if (acMatch) {
      const idx = Number(acMatch[1]);
      const d = dig(target.value);
      if (d.length === 11) {
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(() => {
          identificar(d, idx, target.closest('fieldset'));
        }, 30);
      }
    }
  });

  document.addEventListener('blur', (e) => {
    const target = e.target;
    if (!target || target.tagName !== 'INPUT') return;

    if (target.id === 'documento') {
      const d = dig(target.value);
      if (d.length === 11 || target.value.trim().length >= 5) {
        identificar(d || target.value.trim(), null, target.closest('.fields')?.parentElement);
      }
    } else if (target.id === 'telefone' || target.id === 'email') {
      const nomeVal = document.getElementById('nome')?.value?.trim();
      if (!nomeVal && target.value.trim().length >= 6) {
        identificar(target.value.trim(), null, target.closest('.fields')?.parentElement);
      }
    }

    const acMatch = target.name?.match(/^ac(\d+)-documento$/);
    if (acMatch) {
      const idx = Number(acMatch[1]);
      const d = dig(target.value);
      if (d.length === 11 || target.value.trim().length >= 5) {
        identificar(d || target.value.trim(), idx, target.closest('fieldset'));
      }
    }
  }, true);
})();
